using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ShadowyReflectionEffect", menuName = "Data/Battle/Effects/Sentinels/ShadowyReflection Effect")]
public class ShadowyReflectionEffect : Effect
{
	[SerializeField]
	private OmenLogic omenLogic;

	[SerializeField]
	private BattleAction battleAction;

	public override string GetEffectDescription(int amount, GameObject effectOwner)
	{
		return base.localizationManager.GetLocalizedAtTheStartOfYourTurn(withSpace: true) + battleAction.GetActionDescription(amount).LowercaseFirst();
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		omenLogic.ActivateOmen(battleAction, amount, null, null);
		return amount;
	}
}
